({
  extract: {
    order_number: (text) => text.match(/KG-\d+/)?.[0] ?? null,
    customer_name: (text) => {
      const cust = text.match(/Customer\s*[:\t ]+([^\n]+)/);
      if (cust) {
        const cand = cust[1].trim();
        if (!/^Item\b/i.test(cand)) {
          const name = cand.split("\t")[0].trim();
          if (/^[A-Za-z][A-Za-z.'\- ]*$/.test(name) && /\s/.test(name) && !/\d/.test(name)) return name;
        }
      }
      const from = text.match(/From\s+([^<\n·]+)/);
      if (from) {
        const name = from[1].trim();
        if (name && /^[A-Za-z]/.test(name)) return name;
      }
      const row = text.match(/KG-\d+\s+\d{4}-\d{2}-\d{2}\s+([A-Za-z][A-Za-z.'\-]*\s+[A-Za-z][A-Za-z.'\- ]*)/);
      if (row) return row[1].trim().replace(/\s+/g, " ");
      return null;
    },
    order_date: (text) => text.match(/Order date\s+(\d{4}-\d{2}-\d{2})/i)?.[1] ?? null,
    tracking_number: (text) => text.match(/Tracking number\s*([A-Z0-9]+)/i)?.[1].trim() ?? null,
    courier_status: (text) => text.match(/Status:\s*([A-Za-z ]+)/)?.[1].trim() ?? null
  },
  compute: {
    days_since_order: (v) => {
      if (!v.order_date || !v.today) return null;
      const a = String(v.order_date).trim();
      const b = String(v.today).trim();
      if (!/^\d{4}-\d{2}-\d{2}$/.test(a) || !/^\d{4}-\d{2}-\d{2}$/.test(b)) return null;
      const pa = a.split("-").map(Number);
      const pb = b.split("-").map(Number);
      const da = Date.UTC(pa[0], pa[1] - 1, pa[2]);
      const db = Date.UTC(pb[0], pb[1] - 1, pb[2]);
      if (isNaN(da) || isNaN(db)) return null;
      return Math.round((db - da) / 86400000);
    }
  },
  decide: (v) => {
    const cs = v.courier_status == null ? "" : String(v.courier_status).trim().toLowerCase();
    if (cs === "lost") return { outcome: "refund", rule: 0 };
    if (typeof v.days_since_order === "number" && v.days_since_order > 30) return { outcome: "decline", rule: 1 };
    if (v.photo_shows_damage === true) return { outcome: "send_replacement", rule: 2 };
    return { outcome: "refund", rule: 3 };
  },
  tests: [
    { name: "lost parcel", vars: { courier_status: "Lost", days_since_order: 6, photo_shows_damage: false }, expect: "refund" },
    { name: "old order declines even with damage photo", vars: { courier_status: "Delivered", days_since_order: 45, photo_shows_damage: true }, expect: "decline" },
    { name: "damaged photo sends replacement", vars: { courier_status: "Delivered", days_since_order: 6, photo_shows_damage: true }, expect: "send_replacement" },
    { name: "otherwise refund", vars: { courier_status: "Delivered", days_since_order: 6, photo_shows_damage: false }, expect: "refund" },
    { name: "exactly 30 days is not more than 30", vars: { courier_status: "Delivered", days_since_order: 30, photo_shows_damage: false }, expect: "refund" },
    { name: "missing values fall through to refund", vars: { courier_status: null, days_since_order: null, photo_shows_damage: false }, expect: "refund" },
    { name: "lost case-insensitive with spaces", vars: { courier_status: "  LOST ", days_since_order: 6, photo_shows_damage: false }, expect: "refund" }
  ]
})
